options.helpers:
context.handlebars.registerHelper("timeformat", function (time) {
  console.log("TIME: ", time)
  var date = new Date(time);
  var options = { hour: 'numeric', minute: 'numeric', hour12: true };
  return date.toLocaleTimeString('en-US', options);
});

context.handlebars.registerHelper("degreeformat", function (altitude) {
  var roundedAltitude = Math.round(altitude);
  return roundedAltitude;
});

options.styles:
.responsive-text {
  font-size: calc(0.8em + 0.7vw);
  word-wrap: break-word;
  max-width: 100%;
  line-height: 1.4;
  color: rgb(252, 252, 149);
}

